# Las 9 familias que antes estaban fijas en el código (choices)
FAMILIAS = [
    ('FON', 'Fontanería y saneamiento', 10),
    ('CAL', 'Calefacción y ACS', 20),
    ('CLI', 'Climatización y ventilación', 30),
    ('ELE', 'Electricidad', 40),
    ('SOL', 'Solar fotovoltaica', 50),
    ('DOM', 'Domótica y control', 60),
    ('PIS', 'Piscina y tratamiento de agua', 70),
    ('MOB', 'Mano de obra y servicios', 80),
    ('OTR', 'Otros', 90),
]


def crear_familias(apps, schema_editor):
    Categoria = apps.get_model('gestion', 'Categoria')
    for codigo, nombre, orden in FAMILIAS:
        Categoria.objects.get_or_create(codigo=codigo, defaults={'nombre': nombre, 'orden': orden})


def pasar_grupos_a_tipos(apps, schema_editor):
    # Cada pareja familia + grupo (texto) se convierte en un Tipo, y el material apunta a él
    Material = apps.get_model('gestion', 'Material')
    Tipo = apps.get_model('gestion', 'Tipo')
    for material in Material.objects.exclude(grupo=''):
        tipo, creado = Tipo.objects.get_or_create(nombre=material.grupo, categoria_id=material.categoria)
        material.tipo = tipo
        material.save()


